import codecs
import collections
import configparser
import csv
import datetime
import json
import os
import urllib.parse
from pickle import UnpicklingError
import yaml
from IQCommon import pandas as pd, ParserError, EmptyDataError
from IQCommon.exception import get_traceback_message
from IQCommon.logger import system_log
from IQCommon.i18n import get_local_text as _
DEFAULT = object
INI_FORMAT = ['.ini', '.conf']
YML_FORMAT = ['.yml', '.yaml']
JSON_FORMAT = ['.json']
def full_update(src_dict, drt_dict):
    for key, value in src_dict.items():
        if (key in drt_dict and isinstance(drt_dict[key], collections.abc.Mapping) and isinstance(value, collections.abc.Mapping)):
            full_update(value, drt_dict[key])
            continue
        drt_dict[key] = value
        continue
def load_ini(path):
    config = configparser.ConfigParser()
    return {section.name: {option: value for option, value in section.items()} for section in config.values()}
def load_yaml(path):
    with codecs.open(path, encoding='utf-8') as f:
        loader = yaml.Loader(f)
        loader.anchors = collections.OrderedDict()
        try:
            loader.get_single_data()
        finally: loader.dispose()
def load_json(path):
    with codecs.open(path, encoding='utf-8') as f:
        return json.loads(f.read())
        return None
PARSE_CONFIG_LIST = ((YML_FORMAT, load_yaml), (JSON_FORMAT, load_json), (INI_FORMAT, load_ini))
class ObjectDict(object):
    _base = None
    def __init__(self, base_dict=None):
        if (base_dict is None):
            base_dict = {}
        super(ObjectDict, self).__setattr__('_base', base_dict)
    def __getattr__(self, item):
        try:
            value = self._base[item]
        except (TypeError, KeyError):
            system_log.error('异常信息: %s' % get_traceback_message())
            raise AttributeError(item)
        if isinstance(value, dict):
            value = self.__class__(value)
            _base[item] = self
        return value
    def update(self, other_one):
        full_update(other_one._base, self._base)
    def __setattr__(self, key, value):
        self._base[key] = value
    def __repr__(self):
        return self._base.__repr__()
    def to_dict(self):
        return {k: v.to_dict() if isinstance(v, ObjectDict) else v for k, v in self._base.items()}
    return (__classcell__ := __class__)
def read_config(config_path):
    if (not os.path.exists(config_path)):
        raise FileExistsError(config_path)
    for format_list, parse_config_func in PARSE_CONFIG_LIST:
        for format_type in format_list:
            if config_path.endswith(format_type):
                parse_config_func(config_path)
                break
    else:
        for format_list, parse_config_func in PARSE_CONFIG_LIST:
            try:
                return parse_config_func(config_path)
            except (yaml, json, configparser): system_log.error('异常信息: %s' % get_traceback_message())
        else:
            raise TypeError('Unsupport File Type: {}'.format(config_path))
DB_DEFAULT_DRIVER = {'mysql': 'pymysql'}
def parse_db_url(config):
    dialect = config.pop('dialect', 'mysql')
    driver = (config.pop('driver', None) or DB_DEFAULT_DRIVER.get(dialect))
    if (not driver):
        agreement = dialect
    agreement = '{}+{}'.format(dialect, driver)
    user_name = config.pop('user', None)
    if (user_name is not None):
        user_name = urllib.parse.quote_plus(user_name)
        passwd = config.pop('passwd', None)
        if (passwd is None):
            user_name_password = user_name
        else:
            passwd = urllib.parse.quote_plus(passwd)
            user_name_password = '{}:{}'.format(user_name, passwd)
        user_name_password += '@'
    else:
        user_name_password = ''
    host = config.pop('host', '127.0.0.1')
    port = config.pop('port', 3306)
    db = config.pop('db', 'iqe_data')
    db = urllib.parse.quote_plus(db)
    charset = config.pop('charset', None)
    if (charset is None):
        charset = ''
    else:
        charset = '?charset={}'.format(charset)
    return '{}://{}{}:{}/{}{}'.format(agreement, user_name_password, host, port, db, charset)
def get_original_function(func):
    func_wrapped = getattr(func, '__wrapped__', None)
    while func_wrapped:
        func = func_wrapped
        func_wrapped = getattr(func, '__wrapped__', None)
    return func
READ_ERROR_MESSAGE_TEMPLATE = '获取数据异常: {traceback_message}'
class FileReader(object):
    _base_method = None
    _exceptions = ()
    def __init__(self, default=DEFAULT, error_message_template=READ_ERROR_MESSAGE_TEMPLATE, error_message_dict=None, logger=system_log, level='error'):
        if (error_message_dict is None):
            self.error_message_dict = {}
        else:
            self.error_message_dict = error_message_dict
        self.logger_method = getattr(logger, level, system_log.error)
        self.default = default
        self.error_message_template = error_message_template
        self.logger = logger
        self.level = level
    def __call__(self, file_path, *args, **kwargs):
        try:
            return self._base_method(file_path, *args, **kwargs)
            return None
        except:
            system_log.error('异常信息: %s' % get_traceback_message())
            self.logger_method(_(self.error_message_template.format(**dict(self.error_message_dict, datetime=datetime.datetime.now(), traceback_message=get_traceback_message()))))
            return self.default
    def get_default(self):
        if hasattr(self.default, 'copy'):
            try:
                return self.default.copy()
            except (AttributeError, TypeError): system_log.error('异常信息: %s' % get_traceback_message())
        return self.default
    def __repr__(self):
        return '<{method_name}: default: {default}, error_message_template:{error_message_template}, error_message_dict:{error_message_dict}, logger: {logger}, level: {level}>'.format(method_name=self._base_method.__name__, default=self.default, error_message_template=self.error_message_template, error_message_dict=self.error_message_dict, logger=self.logger, level=self.level)
class PickleReader(FileReader):
    _base_method = staticmethod(pd.read_pickle)
    _exceptions = (FileNotFoundError, UnpicklingError, ImportError, AttributeError)
class CsvReader(FileReader):
    _base_method = pd.read_csv
    _exceptions = (FileNotFoundError, ParserError, EmptyDataError, csv.Error)
def import_plugin(plugin_name):
    from importlib import import_module
    try:
        return import_module(plugin_name)
        return None
    except Exception as e:
        system_log.error('******************************')
        system_log.error('Mod Import Error: {}, error: {}', plugin_name, get_traceback_message())
        system_log.error('******************************')
        raise e
